def eulerian_num(n, m):
    # Function to calculate the binomial coefficient
    def binomial_coefficient(n, k):
        from math import factorial

        # Handle the case where n or k are zero
        if k == 0 or k == n:
            return 1

        # Ensure non-negative values
        if n >= 0 and k >= 0:
            return factorial(n) // (factorial(k) * factorial(n - k))
        else:
            return 0 # Handle the case where n or k are negative

    # Eulerian number formula
    eulerian = sum((-1)**k * binomial_coefficient(n - k, m) * (n - k)**m for k in range(n + 1))
